#include "settings.h"

#include <QFile>
#include <QJsonDocument>
#include <QJsonObject>

Settings loadSettings(const QString &path)
{
    QFile file(path);
    if (!file.open(QIODevice::ReadOnly))
        return {};

    const QJsonObject root = QJsonDocument::fromJson(file.readAll()).object();

    Settings settings;
    settings.host = root.value("host").toString();
    settings.port = root.value("port").toInt();
    settings.retries = root.value("retries").toInt();
    return settings;
}

