#include <optional>

#include <QDebug>

std::optional<Settings> loadSettings(const QString &path)
{
    QFile file(path);
    if (!file.open(QIODevice::ReadOnly)) {
        qWarning() << path << file.errorString();
        return std::nullopt;
    }

    QJsonParseError error;
    const QJsonDocument doc = QJsonDocument::fromJson(file.readAll(), &error);
    if (error.error != QJsonParseError::NoError) {
        qWarning() << path << "at offset" << error.offset << error.errorString();
        return std::nullopt;
    }
    if (!doc.isObject()) {
        qWarning() << path << "top level must be an object";
        return std::nullopt;
    }

    const QJsonObject root = doc.object();
    Settings settings;
    settings.host = root.value("host").toString();
    settings.port = root.value("port").toInt();
    settings.retries = root.value("retries").toInt();
    return settings;
}

const QJsonValue port = root.value("port");
if (!port.isUndefined() && !port.isDouble()) {
    qWarning() << path << "port must be a number, got" << port;
    return std::nullopt;
}
settings.port = port.toInt(8080);
